fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition: start + sub.len() <= main.len()
    if start + sub.len() > main.len() {
        // Should never happen if used correctly,
        // but defend by returning false just in case.
        return false;
    }

    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    let m_len = main.len();
    let s_len = sub.len();

    if s_len == 0 {
        // Empty subarray always matches
        return true;
    }
    if s_len > m_len {
        // sub cannot fit inside main
        return false;
    }

    // Iterate over all valid start positions
    for start in 0..=m_len - s_len {
        if check_match_at(main, sub, start) {
            return true;
        }
    }

    false
}